#dc_menu {
    display: flex;
    flex-direction: column;
    align-items: center;
	flex-wrap: wrap;
    gap: 12px;
    padding: 20px;
}

.dc-button {
	flex: 0 0 100%;
    display: flex;
    align-items: center;
	justify-content: center;
    gap: 12px;

    padding: 14px 18px;
    border-radius: 14px;

    cursor: pointer;
    user-select: none;

    background: rgba(40, 40, 40, 0.8);
    border: 1px solid rgba(255,255,255,0.08);

    color: white;
    transition: 0.2s;
    min-width: 220px;
}

.dc-button:hover {
    transform: translateY(-2px);
    background: rgba(60, 60, 60, 0.9);
}

.dc-icon {
    width: 42px;
    height: 42px;
}

.dc-title {
    font-weight: 700;
    font-size: 16px;
}

.dc-sub {
    font-size: 12px;
    opacity: 0.7;
}
